solution:
#include <stdio.h>

int main(void) {
    int seconds;
    scanf("%d", &seconds);
    int h = seconds / 3600;
    int m = seconds % 3600 / 60;
    int s = seconds % 60;
    printf("%02d:%02d:%02d\n", h, m, s);
    return 0;
}
